foreach ($code in $langs.Keys) {
  $json = $langs[$code] | ConvertTo-Json -Depth 10
  $path = Join-Path $outDir "$code.json"
  Set-Content -LiteralPath $path -Value $json -Encoding Utf8
  Write-Host "$code.json OK"
}
Write-Host "Done: $($langs.Count) languages"
